int x = 40;   // 101000 in binary
System.out.println((x & (x - 1)) + " " + Integer.bitCount(x)
        + " " + Integer.bitCount(x & (x - 1)));

int a = 12, b = 5;
a = a ^ b;
b = a ^ b;
a = a ^ b;
System.out.println(a + " " + b);

int[] a = {2, 1, 1, 3};
int k = 4, left = 0, best = 0, sum = 0;
for (int right = 0; right < a.length; right++) {
    sum += a[right];
    while (sum > k) { sum -= a[left]; left++; }
    best = Math.max(best, right - left + 1);
}
System.out.println(best);

int[] a = {2, 4, 1, 3};
int[] p = new int[5];
for (int i = 0; i < 4; i++) p[i + 1] = p[i] + a[i];
System.out.println(p[4] - p[1]);

int[] a = {4, 1, 2, 1, 2};
int r = 0;
for (int v : a) r ^= v;
System.out.println(r);

int[] a = {1, 5, 2, 3};
int k = 2, sum = 0, best = 0;
for (int i = 0; i < k; i++) sum += a[i];
best = sum;
for (int i = k; i < a.length; i++) {
    sum += a[i] - a[i - k];
    best = Math.max(best, sum);
}
System.out.println(best);

int x = 29;                 // 11101 in binary
int ones = 0;
while (x != 0) {
    x = x & (x - 1);
    ones++;
}
System.out.println(ones + " " + Integer.bitCount(29));

int[] a = {1, 3, 5, 8};   // sorted
int target = 8, i = 0, j = 3;
while (i < j) {
    int s = a[i] + a[j];
    if (s == target) { System.out.println(a[i] + "+" + a[j]); break; }
    if (s < target) i++; else j--;
}
